-- Cash flow cell (cash-flow), generated by solo-cell-kit from cell.yaml.
-- Every row belongs to a workspace and is visible only while the transaction
-- is bound to it (app.workspace_id). Do not edit once applied; add a new migration.

CREATE SCHEMA cash_flow;

CREATE FUNCTION cash_flow.current_workspace() RETURNS uuid
LANGUAGE sql STABLE AS $$
    SELECT nullif(current_setting('app.workspace_id', true), '')::uuid
$$;

CREATE TABLE cash_flow.cashflow_plans (
    workspace_id             uuid NOT NULL,
    id                       bigint GENERATED BY DEFAULT AS IDENTITY (START WITH 1000000),
    legacy_id                bigint,
    name                     text NOT NULL CHECK (length(name) <= 200 AND length(name) >= 1),
    owner_scope              text NOT NULL DEFAULT 'solo_empire' CHECK (owner_scope IN ('personal', 'solo_empire', 'venture', 'client', 'shared')),
    period_start             date NOT NULL,
    period_end               date NOT NULL,
    expected_inflow          double precision NOT NULL DEFAULT 0 CHECK (expected_inflow >= 0),
    expected_outflow         double precision NOT NULL DEFAULT 0 CHECK (expected_outflow >= 0),
    reserve_target           double precision CHECK (reserve_target IS NULL OR (reserve_target >= 0)),
    currency                 text NOT NULL DEFAULT 'THB' CHECK (length(currency) <= 12),
    status                   text NOT NULL DEFAULT 'draft' CHECK (status IN ('draft', 'active', 'closed', 'cancelled')),
    notes                    text,
    version                  bigint NOT NULL DEFAULT 1,
    created_at               timestamptz NOT NULL DEFAULT now(),
    updated_at               timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (workspace_id, id)
);
CREATE UNIQUE INDEX cashflow_plans_legacy ON cash_flow.cashflow_plans (workspace_id, legacy_id) WHERE legacy_id IS NOT NULL;
CREATE INDEX cashflow_plans_owner_scope ON cash_flow.cashflow_plans (workspace_id, owner_scope);
CREATE INDEX cashflow_plans_status ON cash_flow.cashflow_plans (workspace_id, status);

-- Idempotent creates: a key reserves the record id before the platform execution starts.
CREATE TABLE cash_flow.create_keys (
    workspace_id uuid NOT NULL,
    actor        uuid NOT NULL,
    kind         text NOT NULL CHECK (kind IN ('cashflow-plan')),
    key          text NOT NULL CHECK (length(key) BETWEEN 8 AND 200),
    record_id    bigint NOT NULL,
    created_at   timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (workspace_id, actor, kind, key)
);

-- Graph events, written in the same transaction as the change (at-least-once delivery).
CREATE TABLE cash_flow.outbox (
    id              uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    workspace_id    uuid NOT NULL,
    type            text NOT NULL,
    subject         text NOT NULL,
    execution_id    uuid,
    classification  text NOT NULL DEFAULT 'confidential',
    payload         jsonb NOT NULL,
    occurred_at     timestamptz NOT NULL DEFAULT now(),
    published_at    timestamptz,
    attempts        integer NOT NULL DEFAULT 0,
    next_attempt_at timestamptz NOT NULL DEFAULT now(),
    last_error      text,
    correlation_id  text
);
CREATE INDEX outbox_pending ON cash_flow.outbox (next_attempt_at) WHERE published_at IS NULL;

DO $$
DECLARE
    t text;
BEGIN
    FOREACH t IN ARRAY ARRAY['cashflow_plans', 'create_keys', 'outbox'] LOOP
        EXECUTE format('ALTER TABLE cash_flow.%I ENABLE ROW LEVEL SECURITY', t);
        EXECUTE format('ALTER TABLE cash_flow.%I FORCE ROW LEVEL SECURITY', t);
        EXECUTE format('CREATE POLICY workspace_isolation ON cash_flow.%I'
                       ' USING (workspace_id = cash_flow.current_workspace())'
                       ' WITH CHECK (workspace_id = cash_flow.current_workspace())', t);
    END LOOP;
END
$$;

GRANT USAGE ON SCHEMA cash_flow TO cash_flow_api;
GRANT EXECUTE ON FUNCTION cash_flow.current_workspace() TO cash_flow_api;
GRANT SELECT, INSERT, UPDATE, DELETE ON cash_flow.cashflow_plans TO cash_flow_api;
GRANT USAGE ON SEQUENCE cash_flow.cashflow_plans_id_seq TO cash_flow_api;
GRANT SELECT, INSERT ON cash_flow.create_keys TO cash_flow_api;
GRANT SELECT, INSERT ON cash_flow.outbox TO cash_flow_api;
GRANT UPDATE (execution_id, published_at, attempts, next_attempt_at, last_error) ON cash_flow.outbox TO cash_flow_api;

-- The publisher sweeps the outbox of one workspace per token; it reads past RLS for the outbox only.
CREATE POLICY publisher_sweep ON cash_flow.outbox TO cash_flow_publisher USING (true) WITH CHECK (true);
GRANT USAGE ON SCHEMA cash_flow TO cash_flow_publisher;
GRANT SELECT ON cash_flow.outbox TO cash_flow_publisher;
GRANT UPDATE (published_at, attempts, next_attempt_at, last_error) ON cash_flow.outbox TO cash_flow_publisher;
